      "Vous entendez alors une brusque explosion de verre et les voix affolées de vos co®. pagnons. et vous pensez qu'un pistolet à vapeur a réussi à briser la verrière mais, quand vous rou. vrez les yeux, c'est pour voir que la situation est encore plus désespérée que vous ne l'imaginiez.",
