      "Vous faites appel à votre maîtrise de cette Grande Discipline pour lui lancer une attaque psychique. Le sergent recule et agrippe sa tête de ses mains. La douleur est telle qu'il tombe inconscient. VOIE empoignez son corps inanimé avant qu'il ne s'effondre, et appelez les autres gardes à votre secours, prétextant un malaise de leur chef.",
      "Ils accourent et, pendant qu'ils s'occupent de leui supérieur, vous vous faufilez dans la caserne avec vos compagnons. Plusieurs chariots sont parqués derrière la porte principale, ils sont pleins de provisions et sont en train d'être déchargés. Vos compagnons et vous vous approchez du premier chariot et soulevez chacun un cageot.",
      "Vous rejoignez alors avec un air dégagé les hommes qui font queue devant le magasin de vivres au milieu de ls caseme. Vous déposez votre charge puis retournez en reprendre d'autres. En cours de route, vos sens Kaï détectent une porte qui n'est pas fermée à clé Vous prévenez discrètement les éclaireurs et von8 vous y engouffrez tous les uns après les autres.",
